from pysat.formula import CNF
from pysat.solvers import Glucose3
from pysat.card import CardEnc

n = 11

# Variable mapping
var = {}
idx = 1
for i in range(n):
    for j in range(i+1, n):
        var[(i,j)] = idx
        idx += 1

num_vars = idx - 1

# Let's test with just the 11-cycle
# Edges of the 11-cycle: (0,1), (1,2), ..., (9,10), (10,0)
cycle_edges = [(i, (i+1)%n) for i in range(n)]
# Normalize to have u < v
cycle_edges_normalized = []
for u,v in cycle_edges:
    if u < v:
        cycle_edges_normalized.append((u,v))
    else:
        cycle_edges_normalized.append((v,u))

print(f"Cycle edges: {cycle_edges_normalized}")

# Create a model for the 11-cycle
model = [0] * num_vars
for (i,j) in cycle_edges_normalized:
    model[var[(i,j)] - 1] = 1

print(f"Model has {sum(1 for m in model if m > 0)} positive literals")

# Now check if this model satisfies the constraints
formula = CNF()

# Degree constraints
for v in range(n):
    incident_vars = []
    for w in range(n):
        if w < v:
            incident_vars.append(var[(w, v)])
        elif w > v:
            incident_vars.append(var[(v, w)])

    formula.extend(CardEnc.atmost(lits=incident_vars, bound=5, top_id=num_vars))
    formula.extend(CardEnc.atleast(lits=incident_vars, bound=2, top_id=num_vars))

# Check degree constraints manually
print("\nChecking degree constraints:")
for v in range(n):
    incident_vars = []
    for w in range(n):
        if w < v:
            incident_vars.append(var[(w, v)])
        elif w > v:
            incident_vars.append(var[(v, w)])

    deg = sum(1 for vidx in incident_vars if model[vidx-1] > 0)
    print(f"  Vertex {v}: degree = {deg}")
    if deg < 2 or deg > 5:
        print(f"    FAILS!")

# Check cycle constraints
print("\nChecking cycle constraints:")
# Triangles
triangle_ok = True
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            e1 = model[var[(i,j)]-1] > 0
            e2 = model[var[(i,k)]-1] > 0
            e3 = model[var[(j,k)]-1] > 0
            if e1 and e2 and e3:
                print(f"  Triangle found: {i},{j},{k}")
                triangle_ok = False
if triangle_ok:
    print("  No triangles - OK")

# 4-cycles
four_cycle_ok = True
for a in range(n):
    for b in range(n):
        if b == a: continue
        for c in range(n):
            if c == a or c == b: continue
            for d in range(n):
                if d == a or d == b or d == c: continue
                edges = []
                for (u,v) in [(a,b), (b,c), (c,d), (d,a)]:
                    if u < v:
                        edges.append(var[(u,v)])
                    else:
                        edges.append(var[(v,u)])
                if all(model[e-1] > 0 for e in edges):
                    print(f"  4-cycle found: {a},{b},{c},{d}")
                    four_cycle_ok = False
if four_cycle_ok:
    print("  No 4-cycles - OK")

# 5-cycles
five_cycle_ok = True
for a in range(n):
    for b in range(n):
        if b == a: continue
        for c in range(n):
            if c == a or c == b: continue
            for d in range(n):
                if d == a or d == b or d == c: continue
                for e in range(n):
                    if e == a or e == b or e == c or e == d: continue
                    edges = []
                    for (u,v) in [(a,b), (b,c), (c,d), (d,e), (e,a)]:
                        if u < v:
                            edges.append(var[(u,v)])
                        else:
                            edges.append(var[(v,u)])
                    if all(model[ei-1] > 0 for ei in edges):
                        print(f"  5-cycle found: {a},{b},{c},{d},{e}")
                        five_cycle_ok = False
if five_cycle_ok:
    print("  No 5-cycles - OK")

